#!/usr/bin/env python3
import argparse
import json

DEFAULT_SEPARATOR = ","

def parse_items(raw):
    return [part for part in raw.split(DEFAULT_SEPARATOR) if part]

def summarize(items):
    return {"items": items, "total": len(items)}

def build_parser():
    parser = argparse.ArgumentParser()
    parser.add_argument("--items", required=True)
    return parser

def main():
    args = build_parser().parse_args()
    items = parse_items(args.items)
    print(json.dumps(summarize(items), ensure_ascii=False, sort_keys=True))

if __name__ == "__main__":
    main()

